2. Remove Elements: The Queue class provides two different methods to remove elements and the methods are:Clear() Method: The Clear()is used to remove the objects from the queue.Dequeue() Method: The Dequeue() removes the beginning element of the queue.Example: This example displays the contents of the Queue before and after removal.
            C#

    // C# Program to remove
//  elements from a queue
using System;
using System.Collections.Generic;

class Geeks {
    public static void Main(string[] args)
    {
        // Initialize a queue
        Queue<string> q = new Queue<string>();

        // Inserting elements into the 
        // queue using Enqueue()
        q.Enqueue("Geeks");
        q.Enqueue("For");
        q.Enqueue("Geeks");
        q.Enqueue("For");

        // Initial queue
        Console.WriteLine("Initial queue: ");
        foreach(var item in q) { 
          Console.WriteLine(item); 
        }

        // Removing the front element
        q.Dequeue();

        // Final queue after removal
        Console.WriteLine("\nUpdated queue after Dequeue:");
        foreach(var item in q) { 
          Console.WriteLine(item); 
        }
    }
}

